-- 03_migracion.sql - Migra las mediciones historicas de calidad (drenes + superficial, 2022-2026)
--   * pozos_monitoreo:        in-situ por medicion (ce, ph, std, t) + campana, tipo=drene/calidad agua
--   * calidad_agua_laboratorio: parametros extendidos por medicion, enlazados por id_medicion, con tipo
--   Los puntos se resuelven contra drenes_catastro / calidad_catastro por ubicacion+coordenadas.
\set ON_ERROR_STOP on

BEGIN;

DO $$
DECLARE
    r       RECORD;
    newmed  INTEGER;
    n_th   INTEGER := 0;
BEGIN
    FOR r IN
        SELECT u.*,
               CASE WHEN u.tipo = 'drene' THEN d.id_dren ELSE c.id_calidad END AS id_catalogo
        FROM ( SELECT btrim(upper(coalesce(nullif(ubicacion,''),'(SIN NOMBRE)'))) || '|' || coalesce(cooreste::text,'') || '|' || coalesce(coornorte::text,'') AS clv, geom, cooreste, coornorte, zona, cota, departamento, provincia, distrito, ubicacion, descripcion, aaa, ala, uh, fechamonitoreo::date AS fechamonitoreo, fechamonitoreo::date + horamonitoreo::time AS horamonitoreo, orden, ce, ph, std, t, turbidez, nitratos, nitritos, cromohexavalente, cobre, manganeso, sulfatos, hierro, zinc, cloruros, coliformestotales, coliformestermotolerantes, escherichiacoli, "dureza" AS "durezatotal", NULL::double precision AS "calcio", NULL::double precision AS "cloruro", NULL::double precision AS "potasio", NULL::double precision AS "sodio", NULL::double precision AS "amonio", NULL::double precision AS "magnesio", "observacion" AS "observaciones", CASE extract(MONTH FROM fechamonitoreo::date)::int WHEN 1 THEN 'ENERO' WHEN 2 THEN 'FEBRERO' WHEN 3 THEN 'MARZO' WHEN 4 THEN 'ABRIL' WHEN 5 THEN 'MAYO' WHEN 6 THEN 'JUNIO' WHEN 7 THEN 'JULIO' WHEN 8 THEN 'AGOSTO' WHEN 9 THEN 'SETIEMBRE' WHEN 10 THEN 'OCTUBRE' WHEN 11 THEN 'NOVIEMBRE' WHEN 12 THEN 'DICIEMBRE' END || ' ' || extract(YEAR FROM fechamonitoreo::date)::int AS campana, 'drene' AS tipo
FROM calidadaguadrenada2022.monitoreodrenajeabril WHERE (fechamonitoreo IS NOT NULL OR cooreste IS NOT NULL OR coornorte IS NOT NULL OR ce IS NOT NULL OR ph IS NOT NULL OR turbidez IS NOT NULL)
UNION ALL
SELECT btrim(upper(coalesce(nullif(ubicacion,''),'(SIN NOMBRE)'))) || '|' || coalesce(cooreste::text,'') || '|' || coalesce(coornorte::text,'') AS clv, geom, cooreste, coornorte, zona, cota, departamento, provincia, distrito, ubicacion, descripcion, aaa, ala, uh, fechamonitoreo::date AS fechamonitoreo, fechamonitoreo::date + horamonitoreo::time AS horamonitoreo, orden, ce, ph, std, t, turbidez, nitratos, nitritos, cromohexavalente, cobre, manganeso, sulfatos, hierro, zinc, cloruros, coliformestotales, coliformestermotolerantes, escherichiacoli, "dureza" AS "durezatotal", NULL::double precision AS "calcio", NULL::double precision AS "cloruro", NULL::double precision AS "potasio", NULL::double precision AS "sodio", NULL::double precision AS "amonio", NULL::double precision AS "magnesio", "observacion" AS "observaciones", CASE extract(MONTH FROM fechamonitoreo::date)::int WHEN 1 THEN 'ENERO' WHEN 2 THEN 'FEBRERO' WHEN 3 THEN 'MARZO' WHEN 4 THEN 'ABRIL' WHEN 5 THEN 'MAYO' WHEN 6 THEN 'JUNIO' WHEN 7 THEN 'JULIO' WHEN 8 THEN 'AGOSTO' WHEN 9 THEN 'SETIEMBRE' WHEN 10 THEN 'OCTUBRE' WHEN 11 THEN 'NOVIEMBRE' WHEN 12 THEN 'DICIEMBRE' END || ' ' || extract(YEAR FROM fechamonitoreo::date)::int AS campana, 'drene' AS tipo
FROM calidadaguadrenada2022.monitoreodrenajeagosto WHERE (fechamonitoreo IS NOT NULL OR cooreste IS NOT NULL OR coornorte IS NOT NULL OR ce IS NOT NULL OR ph IS NOT NULL OR turbidez IS NOT NULL)
UNION ALL
